import subprocess, itertools
def run(args, inp=b''):
    p=subprocess.run(["./executable"]+args, input=inp, capture_output=True)
    return p.stdout.decode(), p.stderr.decode(), p.returncode
def uval(v):
    s=f"json.a = {v};\n"; out,err,rc=run(["-u"], s.encode())
    return rc, (out.strip() if out else err.strip())

alphabet="abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789_$."
for prefix in ["true","false","null","t","f","n","tru","fals","nul","tr","fa","nu"]:
    accepts=[]
    for ch in alphabet:
        rc,res=uval(prefix+ch)
        if rc==0: accepts.append(ch)
    print(prefix, "accept-following -> success:", "".join(accepts))

# multiple suffix possibilities maybe token continues only one extra?
for v in ["trueee","trueeee","truer","trueru","truex","trueex","falset","falsea","falseaa","falseal","falsealse","falsee","falseel","nullu","nulll","nulllu","nulllul","nulln"]:
    print(v, uval(v))
# malformed literals starting letters
for v in ["tx","txx","fx","nx","ta","tc","na","e","a","x","truex;","truth","truest","falso","nulx","nulllx","nully","true ","false ","t "]:
    print(repr(v), uval(v))
PY
"}

