import subprocess, json, unicodedata, sys
EXE="/workspace/executable"
def batch(keys):
    obj={k:1 for k in keys}
    inp=json.dumps(obj, ensure_ascii=False).encode()
    p=subprocess.run([EXE], input=inp, capture_output=True)
    out=p.stdout.decode()
    res={}
    dec=json.JSONDecoder()
    for line in out.splitlines()[1:]:
        if line.startswith('json.'):
            assert line.endswith(' = 1;')
            k=line[len('json.'):-len(' = 1;')]
            res[k]=True
        elif line.startswith('json['):
            # second char [
            s,idx=dec.raw_decode(line,5)
            res[s]=False
        else:
            print("unexpected",repr(line),file=sys.stderr)
    if len(res)!=len(keys):
        print("missing",len(keys),len(res), set(keys)-set(res), file=sys.stderr)
    return res

def rule_start(ch):
    c=unicodedata.category(ch)
    return ch in '_$' or c in ('Lu','Ll','Lm','Lo','Nl')
def rule_cont(ch):
    c=unicodedata.category(ch)
    return ch in '_$' or c in ('Lu','Ll','Lm','Lo','Nl','Mn','Mc','Nd','Pc')

exceptions_start=[]
exceptions_cont=[]
all_cps=[cp for cp in range(0x10000) if not (0xD800<=cp<=0xDFFF)]
# start test keys: ch + 'x'  (x ascii)
for offset in range(0,len(all_cps),2000):
    cps=all_cps[offset:offset+2000]
    keys=[chr(cp)+"x" for cp in cps]
    res=batch(keys)
    for cp in cps:
        ch=chr(cp); exp=rule_start(ch); act=res.get(ch+"x")
        if act is None: continue
        if exp!=act:
            exceptions_start.append((cp,unicodedata.category(ch),exp,act))
    keys=["x"+chr(cp) for cp in cps]
    res=batch(keys)
    for cp in cps:
        ch=chr(cp); exp=rule_cont(ch); act=res.get("x"+ch)
        if act is None: continue
        if exp!=act:
            exceptions_cont.append((cp,unicodedata.category(ch),exp,act))
    print("done",hex(offset), "start exc",len(exceptions_start),"cont exc",len(exceptions_cont), flush=True)

print("START EXCEPTIONS")
for e in exceptions_start: print(hex(e[0]),e)
print("CONT EXCEPTIONS")
for e in exceptions_cont: print(hex(e[0]),e)
PY
