actions.command:
cat > main.go <<'EOF'
package main

import (
	"bufio"
	"bytes"
	"crypto/tls"
	"encoding/json"
	"errors"
	"flag"
	"fmt"
	"io"
	"net/http"
	"net/url"
	"os"
	"regexp"
	"sort"
	"strconv"
	"strings"
	"syscall"
	"unicode"
	"unicode/utf8"
	"unsafe"
)

const version = "dev"

const usageText = `Transform JSON (from a file, URL, or stdin) into discrete assignments to make it greppable

Usage:
  gron [OPTIONS] [FILE|URL|-]

Options:
  -u, --ungron     Reverse the operation (turn assignments back into JSON)
  -v, --values     Print just the values of provided assignments
  -c, --colorize   Colorize output (default on tty)
  -m, --monochrome Monochrome (don't colorize output)
  -s, --stream     Treat each line of input as a separate JSON object
  -k, --insecure   Disable certificate validation
  -x, --proxy      Set proxy configuration
      --noproxy    Comma-separated list of hosts for which not to use a proxy, if one is specified.
  -j, --json       Represent gron data as JSON stream
      --no-sort    Don't sort output (faster)
      --version    Print version information

Exit Codes:
  0	OK
  1	Failed to open file
  2	Failed to read input
  3	Failed to form statements
  4	Failed to fetch URL
  5	Failed to parse statements
  6	Failed to encode JSON

Examples:
  gron /tmp/apiresponse.json
  gron http://jsonplaceholder.typicode.com/users/1 
  curl -s http://jsonplaceholder.typicode.com/users/1 | gron
  gron http://jsonplaceholder.typicode.com/users/1 | grep company | gron --ungron
`

var (
	optUngron    bool
	optValues    bool
	optColor bool
	optMono      bool
	optStream    bool
	optInsecure  bool
	optJSON      bool
	optNoSort    bool
	optVersion   bool
	optProxy     string
	optNoProxy   string
	proxyPassed  bool
	noproxyPassed bool
	colorOn      bool
)

func fail(code int, format string, args ...interface{}) {
	fmt.Fprintf(os.Stderr, format+"\n", args...)
	os.Exit(code)
}

func isTTY(f *os.File) bool {
	var termios [128]byte
	_, _, errno := syscall.Syscall(syscall.SYS_IOCTL, f.Fd(), uintptr(syscall.TCGETS), uintptr(unsafe.Pointer(&termios[0])))
	return errno == 0
}

func computeColor() bool {
	if os.Getenv("NO_COLOR") != "" {
		return false
	}
	if optColor {
		return true
	}
	if optMono {
		return false
	}
	if os.Getenv("TERM") == "dumb" {
		return false
	}
	return isTTY(os.Stdout)
}

// Colour helpers. When colour is off they return the input unchanged.
func cBlueBold(s string) string {
	if !colorOn { return s }
	return "\x1b[34;1m" + s + "\x1b[0;22m"
}
func cMagenta(s string) string {
	if !colorOn { return s }
	return "\x1b[35m" + s + "\x1b[0m"
}
func cYellow(s string) string {
	if !colorOn { return s }
	return "\x1b[33m" + s + "\x1b[0m"
}
func cRed(s string) string {
	if !colorOn { return s }
	return "\x1b[31m" + s + "\x1b[0m"
}
func cCyan(s string) string {
	if !colorOn { return s }
	return "\x1b[36m" + s + "\x1b[0m"
}
func cGreen(s string) string {
	if !colorOn { return s }
	return "\x1b[32m" + s + "\x1b[0m"
}
func cBold(s string) string {
	if !colorOn { return s }
	return "\x1b[1m" + s + "\x1b[22m"
}

var urlRe = regexp.MustCompile(`(?i)^https?://`)

func fetchURL(raw string) (io.ReadCloser, error) {
	proxyFunc := func(req *http.Request) (*url.URL, error) {
		var proxyStr string
		if proxyPassed {
			proxyStr = optProxy
		} else if req.URL.Scheme == "https" {
			proxyStr = os.Getenv("https_proxy")
		} else {
			proxyStr = os.Getenv("http_proxy")
		}
		if proxyStr == "" {
			return nil, nil
		}
		var noproxy string
		if noproxyPassed {
			noproxy = optNoProxy
		} else {
			noproxy = os.Getenv("no_proxy")
		}
		for _, entry := range strings.Split(noproxy, ",") {
			if entry == req.URL.Host {
				return nil, nil
			}
			if strings.HasPrefix(entry, ".") && strings.HasSuffix(req.URL.Host, entry) {
				return nil, nil
			}
		}
		u, err := url.Parse(proxyStr)
		if err != nil {
			return nil, nil
		}
		return u, nil
	}
	tr := &http.Transport{
		Proxy: proxyFunc,
		TLSClientConfig: &tls.Config{InsecureSkipVerify: optInsecure},
	}
	client := &http.Client{Transport: tr}
	req, err := http.NewRequest("GET", raw, nil)
	if err != nil {
		return nil, err
	}
	req.Header.Set("User-Agent", "gron/"+version)
	req.Header.Set("Accept", "application/json")
	resp, err := client.Do(req)
	if err != nil {
		return nil, err
	}
	return resp.Body, nil
}

func main() {
	flag.BoolVar(&optUngron, "u", false, "")
	flag.BoolVar(&optUngron, "ungron", false, "")
	flag.BoolVar(&optValues, "v", false, "")
	flag.BoolVar(&optValues, "values", false, "")
	flag.BoolVar(&optColor, "c", false, "")
	flag.BoolVar(&optColor, "colorize", false, "")
	flag.BoolVar(&optMono, "m", false, "")
	flag.BoolVar(&optMono, "monochrome", false, "")
	flag.BoolVar(&optStream, "s", false, "")
	flag.BoolVar(&optStream, "stream", false, "")
	flag.BoolVar(&optInsecure, "k", false, "")
	flag.BoolVar(&optInsecure, "insecure", false, "")
	flag.StringVar(&optProxy, "x", "", "")
	flag.StringVar(&optProxy, "proxy", "", "")
	flag.StringVar(&optNoProxy, "noproxy", "", "")
	flag.BoolVar(&optJSON, "j", false, "")
	flag.BoolVar(&optJSON, "json", false, "")
	flag.BoolVar(&optNoSort, "no-sort", false, "")
	flag.BoolVar(&optVersion, "version", false, "")
	flag.Usage = func() { fmt.Fprint(os.Stderr, usageText) }
	flag.Parse()

	if optVersion {
		fmt.Println("gron version " + version)
		return
	}
	flag.Visit(func(f *flag.Flag) {
		if f.Name == "x" || f.Name == "proxy" {
			proxyPassed = true
		}
		if f.Name == "noproxy" {
			noproxyPassed = true
		}
	})
	colorOn = computeColor()

	var input io.Reader
	var closer io.Closer
	filename := flag.Arg(0)
	switch {
	case filename == "" || filename == "-":
		input = os.Stdin
	case urlRe.MatchString(filename):
		body, err := fetchURL(filename)
		if err != nil {
			fmt.Fprintln(os.Stderr, err)
			os.Exit(4)
		}
		input = body
		closer = body
	default:
		f, err := os.Open(filename)
		if err != nil {
			fmt.Fprintln(os.Stderr, err)
			os.Exit(1)
		}
		input = f
		closer = f
	}
	if closer != nil {
		defer closer.Close()
	}

	if optUngron {
		doUngron(input)
		return
	}
	if optValues {
		doValues()
		return
	}
	if optStream {
		doGronStream(input)
		return
	}
	doGron(input)
}

// ---------------------------------------------------------------------------
// Identifier and quoting helpers
// ---------------------------------------------------------------------------

func isBareStart(r rune) bool {
	if r == '_' || r == '$' {
		return true
	}
	return unicode.In(r, unicode.Lu, unicode.Ll, unicode.Lm, unicode.Lo, unicode.Nl)
}

func isBareCont(r rune) bool {
	if r == '_' || r == '$' {
		return true
	}
	return unicode.In(r, unicode.Lu, unicode.Ll, unicode.Lm, unicode.Lo, unicode.Nl, unicode.Mn, unicode.Mc, unicode.Nd, unicode.Pc)
}

var reservedWords = map[string]bool{
	"break": true, "case": true, "catch": true, "class": true, "const": true,
	"continue": true, "debugger": true, "default": true, "delete": true, "do": true,
	"else": true, "export": true, "extends": true, "finally": true, "for": true,
	"function": true, "if": true, "import": true, "in": true, "instanceof": true,
	"new": true, "return": true, "super": true, "switch": true, "this": true,
	"throw": true, "try": true, "typeof": true, "var": true, "void": true,
	"while": true, "with": true, "yield": true,
	"true": true, "false": true, "null": true,
}

func isValidBareword(s string) bool {
	if s == "" || reservedWords[s] {
		return false
	}
	for i, r := range s {
		if i == 0 {
			if !isBareStart(r) {
				return false
			}
		} else if !isBareCont(r) {
			return false
		}
	}
	return true
}

func quoteString(s string) string {
	var b strings.Builder
	b.WriteByte('"')
	for _, r := range s {
		switch r {
		case '"':
			b.WriteString(`\"`)
		case '\\':
			b.WriteString(`\\`)
		case '\b':
			b.WriteString(`\b`)
		case '\f':
			b.WriteString(`\f`)
		case '\n':
			b.WriteString(`\n`)
		case '\r':
			b.WriteString(`\r`)
		case '\t':
			b.WriteString(`\t`)
		default:
			if unicode.IsControl(r) || r == '\u2028' || r == '\u2029' {
				fmt.Fprintf(&b, `\u%04X`, r)
			} else {
				b.WriteRune(r)
			}
		}
	}
	b.WriteByte('"')
	return b.String()
}

// jsonStringContent returns the encoding of s as a JSON string without the
// outer quotes, using Go's standard encoder without HTML escaping.
func jsonStringContent(s string) string {
	var buf bytes.Buffer
	enc := json.NewEncoder(&buf)
	enc.SetEscapeHTML(false)
	_ = enc.Encode(s)
	out := strings.TrimSuffix(buf.String(), "\n")
	if len(out) >= 2 {
		return out[1 : len(out)-1]
	}
	return out
}

// ---------------------------------------------------------------------------
// Gron: JSON -> statements
// ---------------------------------------------------------------------------

type segKind int

const (
	segKey segKind = iota
	segIndex
)

type segment struct {
	kind segKind
	key  string
	idx  int
}

type valKind int

const (
	valString valKind = iota
	valNumber
	valLiteral // bool or null
	valObject
	valArray
)

type gStatement struct {
	segs  []segment
	vtext string
	vkind valKind
}

func valueText(v interface{}) (string, valKind) {
	switch t := v.(type) {
	case map[string]interface{}:
		return "{}", valObject
	case []interface{}:
		return "[]", valArray
	case string:
		return quoteString(t), valString
	case json.Number:
		return t.String(), valNumber
	case bool:
		if t {
			return "true", valLiteral
		}
		return "false", valLiteral
	case nil:
		return "null", valLiteral
	default:
		// Should not happen for JSON-decoded data.
		b, _ := json.Marshal(t)
		return string(b), valNumber
	}
}

func makeStatements(v interface{}, segs []segment, out *[]gStatement) {
	text, kind := valueText(v)
	cp := make([]segment, len(segs))
	copy(cp, segs)
	*out = append(*out, gStatement{segs: cp, vtext: text, vkind: kind})
	switch t := v.(type) {
	case map[string]interface{}:
		for k, val := range t {
			makeStatements(val, append(segs, segment{kind: segKey, key: k}), out)
		}
	case []interface{}:
		for i, val := range t {
			makeStatements(val, append(segs, segment{kind: segIndex, idx: i}), out)
		}
	}
}

func (s gStatement) segmentText(seg segment) string {
	if seg.kind == segIndex {
		return "[" + strconv.Itoa(seg.idx) + "]"
	}
	if isValidBareword(seg.key) {
		return "." + seg.key
	}
	return "[" + quoteString(seg.key) + "]"
}

func (s gStatement) sortKey() string {
	var b strings.Builder
	b.WriteString("json")
	for _, seg := range s.segs {
		if seg.kind == segIndex {
			fmt.Fprintf(&b, "[%020d]", seg.idx)
		} else {
			b.WriteString(s.segmentText(seg))
		}
	}
	b.WriteString(" = ")
	b.WriteString(s.vtext)
	b.WriteString(";")
	return b.String()
}

func sortStatements(stmts []gStatement) {
	sort.Slice(stmts, func(i, j int) bool {
		return stmts[i].sortKey() < stmts[j].sortKey()
	})
}

func coloredValue(text string, kind valKind) string {
	if !colorOn {
		return text
	}
	switch kind {
	case valString:
		return cYellow(text)
	case valNumber:
		return cRed(text)
	case valLiteral:
		return cCyan(text)
	case valObject, valArray:
		return cMagenta(text)
	}
	return text
}

func (s gStatement) String() string {
	var b strings.Builder
	b.WriteString(cBlueBold("json"))
	for _, seg := range s.segs {
		if seg.kind == segIndex {
			b.WriteString(cMagenta("[") + cRed(strconv.Itoa(seg.idx)) + cMagenta("]"))
		} else if isValidBareword(seg.key) {
			b.WriteString(".")
			b.WriteString(cBlueBold(seg.key))
		} else {
			b.WriteString(cMagenta("[") + cYellow(quoteString(seg.key)) + cMagenta("]"))
		}
	}
	b.WriteString(" = ")
	b.WriteString(coloredValue(s.vtext, s.vkind))
	b.WriteString(";")
	return b.String()
}

func (s gStatement) JSONString() string {
	var b strings.Builder
	b.WriteString(cMagenta("["))
	b.WriteString(cMagenta("["))
	for i, seg := range s.segs {
		if i > 0 {
			b.WriteString(",")
		}
		if seg.kind == segIndex {
			b.WriteString(cRed(strconv.Itoa(seg.idx)))
		} else {
			b.WriteString(cYellow(quoteString(seg.key)))
		}
	}
	b.WriteString(cMagenta("]"))
	b.WriteString(",")
	b.WriteString(coloredValue(s.vtext, s.vkind))
	b.WriteString(cMagenta("]"))
	return b.String()
}

func printStatements(stmts []gStatement) {
	for _, s := range stmts {
		if optJSON {
			fmt.Println(s.JSONString())
		} else {
			fmt.Println(s.String())
		}
	}
}

func decodeJSON(r io.Reader) (interface{}, error) {
	dec := json.NewDecoder(r)
	dec.UseNumber()
	var v interface{}
	err := dec.Decode(&v)
	return v, err
}

func doGron(input io.Reader) {
	v, err := decodeJSON(input)
	if err != nil {
		fail(3, "failed to form statements: %s", err)
	}
	var stmts []gStatement
	makeStatements(v, nil, &stmts)
	if !optNoSort {
		sortStatements(stmts)
	}
	printStatements(stmts)
}

func doGronStream(input io.Reader) {
	// Print the root array statement first.
	rootText, rootKind := "[]", valArray
	root := gStatement{segs: nil, vtext: rootText, vkind: rootKind}
	printStatements([]gStatement{root})

	scanner := bufio.NewScanner(input)
	scanner.Buffer(make([]byte, 0, 64*1024), 1024*1024)
	i := 0
	for scanner.Scan() {
		line := scanner.Bytes()
		v, err := decodeJSON(bytes.NewReader(line))
		if err != nil {
			fail(3, "failed to form statements: %s", err)
		}
		var stmts []gStatement
		makeStatements(v, []segment{{kind: segIndex, idx: i}}, &stmts)
		if !optNoSort {
			sortStatements(stmts)
		}
		printStatements(stmts)
		i++
	}
	if err := scanner.Err(); err != nil {
		// Deliberately reproduced formatting quirk: a missing argument.
		fmt.Fprintf(os.Stderr, "error reading multiline input: %s: %s\n", err)
		os.Exit(3)
	}
}

// ---------------------------------------------------------------------------
// Statement parsing (for ungron and values)
// ---------------------------------------------------------------------------

type tokKind int

const (
	tokBare tokKind = iota
	tokQuoted
	tokNumber
	tokLiteral
	tokGeneric
	tokObject
	tokArray
	tokDash
)

type ptoken struct {
	kind tokKind
	text string
}

type parsedStatement struct {
	pathDisplay string
	segments    []ptoken
	tokenCount  int
	hasEquals   bool
	valuePresent bool
	value       ptoken
	terminated  bool
	invalid     bool
}

func (p *parsedStatement) String() string {
	out := p.pathDisplay
	if p.hasEquals {
		out += " = "
		if p.valuePresent {
			out += p.value.text
			if p.terminated {
				out += ";"
			}
		}
	}
	return out
}

func decodeRuneAt(s string, pos int) (rune, int) {
	if pos >= len(s) {
		return utf8.RuneError, 0
	}
	r, size := utf8.DecodeRuneInString(s[pos:])
	return r, size
}

// parseQuotedToken parses a quoted token starting at s[start]=='"'.
// Returns the token text, the position after it, and whether it was closed.
func parseQuotedToken(s string, start int) (string, int, bool) {
	pos := start + 1
	escaped := false
	for pos < len(s) {
		r, size := utf8.DecodeRuneInString(s[pos:])
		if r == utf8.RuneError {
			pos += size
			if pos < len(s) && s[pos] == '"' {
				escaped = false
				continue
			}
			return s[start:pos], pos, false
		}
		pos += size
		if escaped {
			escaped = false
			continue
		}
		if r == '\\' {
			escaped = true
			continue
		}
		if r == '"' {
			return s[start:pos], pos, true
		}
	}
	return s[start:pos], pos, false
}

type stmtParser struct {
	s    string
	pos  int
	stmt parsedStatement
}

func (p *stmtParser) parseBare() {
	start := p.pos
	_, size := decodeRuneAt(p.s, p.pos)
	p.pos += size
	for p.pos < len(p.s) {
		r, sz := decodeRuneAt(p.s, p.pos)
		if r == utf8.RuneError {
			break
		}
		if !isBareCont(r) {
			break
		}
		p.pos += sz
	}
	text := p.s[start:p.pos]
	p.stmt.pathDisplay += text
	p.stmt.tokenCount++
	p.stmt.segments = append(p.stmt.segments, ptoken{kind: tokBare, text: text})
}

// parseBracket parses "[...]" starting at p.pos=='['. On failure it sets
// stmt.invalid.
func (p *stmtParser) parseBracket() {
	p.stmt.pathDisplay += "["
	p.stmt.tokenCount++
	p.pos++ // consume '['
	if p.pos >= len(p.s) {
		p.stmt.invalid = true
		return
	}
	r, _ := decodeRuneAt(p.s, p.pos)
	if r == '"' {
		text, next, complete := parseQuotedToken(p.s, p.pos)
		p.stmt.pathDisplay += text
		p.stmt.tokenCount++
		p.stmt.segments = append(p.stmt.segments, ptoken{kind: tokQuoted, text: text})
		p.pos = next
		if !complete {
			p.stmt.invalid = true
			return
		}
	} else if unicode.IsNumber(r) {
		start := p.pos
		for p.pos < len(p.s) {
			rr, sz := decodeRuneAt(p.s, p.pos)
			if rr == utf8.RuneError || !unicode.IsNumber(rr) {
				break
			}
			p.pos += sz
		}
		text := p.s[start:p.pos]
		p.stmt.pathDisplay += text
		p.stmt.tokenCount++
		p.stmt.segments = append(p.stmt.segments, ptoken{kind: tokNumber, text: text})
	} else {
		p.stmt.invalid = true
		return
	}
	if p.pos < len(p.s) && p.s[p.pos] == ']' {
		p.stmt.pathDisplay += "]"
		p.stmt.tokenCount++
		p.pos++
		return
	}
	p.stmt.invalid = true
}

// spaceToEquals reports whether the spaces at p.pos are followed by '=';
// if so it advances p.pos to that '='.
func (p *stmtParser) spaceToEquals() bool {
	j := p.pos
	for j < len(p.s) && p.s[j] == ' ' {
		j++
	}
	if j < len(p.s) && p.s[j] == '=' {
		p.pos = j
		return true
	}
	return false
}

func (p *stmtParser) afterValue() {
	for p.pos < len(p.s) && p.s[p.pos] == ' ' {
		p.pos++
	}
	if p.pos < len(p.s) && p.s[p.pos] == ';' {
		p.stmt.terminated = true
		p.pos++
	}
}

func (p *stmtParser) parseValue() {
	for p.pos < len(p.s) && p.s[p.pos] == ' ' {
		p.pos++
	}
	if p.pos >= len(p.s) {
		return
	}
	c := p.s[p.pos]
	switch {
	case c == ';':
		p.stmt.valuePresent = true
		p.stmt.value = ptoken{kind: tokGeneric, text: ""}
		p.stmt.terminated = true
		p.pos++
	case c == '"':
		text, next, complete := parseQuotedToken(p.s, p.pos)
		p.stmt.valuePresent = true
		p.stmt.value = ptoken{kind: tokQuoted, text: text}
		p.pos = next
		if complete {
			p.afterValue()
		}
	case c == 't' || c == 'f' || c == 'n':
		var set string
		switch c {
		case 't':
			set = "rue"
		case 'f':
			set = "alse"
		case 'n':
			set = "ul"
		}
		start := p.pos
		p.pos++
		for p.pos < len(p.s) && strings.IndexByte(set, p.s[p.pos]) >= 0 {
			p.pos++
		}
		p.stmt.valuePresent = true
		p.stmt.value = ptoken{kind: tokLiteral, text: p.s[start:p.pos]}
		p.afterValue()
	case c == '{':
		p.stmt.valuePresent = true
		if p.pos+1 < len(p.s) && p.s[p.pos+1] == '}' {
			p.stmt.value = ptoken{kind: tokObject, text: "{}"}
			p.pos += 2
			p.afterValue()
		} else {
			p.stmt.value = ptoken{kind: tokObject, text: "{"}
			p.pos++
		}
	case c == '[':
		p.stmt.valuePresent = true
		if p.pos+1 < len(p.s) && p.s[p.pos+1] == ']' {
			p.stmt.value = ptoken{kind: tokArray, text: "[]"}
			p.pos += 2
			p.afterValue()
		} else {
			p.stmt.value = ptoken{kind: tokArray, text: "["}
			p.pos++
		}
	default:
		// Generic value: consume until ';', EOF, or a RuneError.
		start := p.pos
		for p.pos < len(p.s) {
			r, sz := utf8.DecodeRuneInString(p.s[p.pos:])
			if r == utf8.RuneError {
				p.pos += sz
				p.stmt.valuePresent = true
				p.stmt.value = ptoken{kind: tokGeneric, text: p.s[start:p.pos]}
				if p.pos < len(p.s) && p.s[p.pos] == ';' {
					p.stmt.terminated = true
					p.pos++
				}
				return
			}
			if r == ';' {
				p.stmt.valuePresent = true
				p.stmt.value = ptoken{kind: tokGeneric, text: p.s[start:p.pos]}
				p.stmt.terminated = true
				p.pos++
				return
			}
			p.pos += sz
		}
		p.stmt.valuePresent = true
		p.stmt.value = ptoken{kind: tokGeneric, text: p.s[start:p.pos]}
	}
}

func (p *stmtParser) parseEqualsAndValue() {
	p.pos++ // consume '='
	p.stmt.hasEquals = true
	p.parseValue()
}

func parseStatement(s string) parsedStatement {
	p := &stmtParser{s: s}
	needBare := false
	afterBracket := false
	for {
		if p.pos >= len(p.s) {
			if needBare {
				p.stmt.invalid = true
			}
			break
		}
		r, size := decodeRuneAt(p.s, p.pos)
		if r == utf8.RuneError {
			if needBare {
				p.stmt.invalid = true
			}
			break
		}
		if needBare {
			if isBareStart(r) {
				p.parseBare()
				needBare = false
				afterBracket = false
				continue
			}
			p.stmt.invalid = true
			break
		}
		if p.stmt.tokenCount == 0 {
			// Initial position.
			switch {
			case r == ' ':
				if p.spaceToEquals() {
					p.parseEqualsAndValue()
					return p.stmt
				}
				return p.stmt
			case r == '.':
				p.stmt.pathDisplay += "."
				p.stmt.tokenCount++
				p.pos += size
				needBare = true
			case r == '[':
				p.parseBracket()
				if p.stmt.invalid {
					return p.stmt
				}
				afterBracket = true
			case r == '=':
				p.parseEqualsAndValue()
				return p.stmt
			case r == ';':
				p.stmt.invalid = true
				return p.stmt
			case r == '-':
				p.stmt.pathDisplay += p.s[p.pos:]
				p.stmt.tokenCount++
				p.pos = len(p.s)
				return p.stmt
			case isBareStart(r):
				p.parseBare()
				afterBracket = false
			default:
				p.stmt.invalid = true
				return p.stmt
			}
			continue
		}
		// After a completed path unit.
		switch {
		case r == '.':
			p.stmt.pathDisplay += "."
			p.stmt.tokenCount++
			p.pos += size
			needBare = true
			afterBracket = false
		case r == '[':
			p.parseBracket()
			if p.stmt.invalid {
				return p.stmt
			}
			afterBracket = true
		case r == '=':
			p.parseEqualsAndValue()
			return p.stmt
		case r == ' ':
			if p.spaceToEquals() {
				p.parseEqualsAndValue()
				return p.stmt
			}
			return p.stmt
		case r == ';':
			p.stmt.invalid = true
			return p.stmt
		case r == '-':
			p.stmt.pathDisplay += p.s[p.pos:]
			p.stmt.tokenCount++
			p.pos = len(p.s)
			return p.stmt
		case afterBracket && isBareStart(r):
			p.parseBare()
			afterBracket = false
		default:
			p.stmt.invalid = true
			return p.stmt
		}
	}
	return p.stmt
}

func (p *parsedStatement) isEmpty() bool {
	return p.tokenCount == 0 && !p.hasEquals && !p.invalid
}

func (p *parsedStatement) isSingleSkip() bool {
	return p.tokenCount == 1 && !p.hasEquals && !p.invalid
}

// ---------------------------------------------------------------------------
// Ungron: statements -> JSON
// ---------------------------------------------------------------------------

var (
	errInvalidStatement = errors.New("invalid statement")
	errNoValue          = errors.New("statement has no value")
)

type stmtError struct {
	stmt *parsedStatement
	err  error
}

func (e *stmtError) Error() string {
	return fmt.Sprintf("ungron failed for `%s`: %s", e.stmt.String(), e.err.Error())
}

func parseValueToken(text string) (interface{}, error) {
	dec := json.NewDecoder(strings.NewReader(text))
	dec.UseNumber()
	var v interface{}
	if err := dec.Decode(&v); err != nil {
		return nil, fmt.Errorf("invalid value `%s`", text)
	}
	return v, nil
}

// statementToInterface converts one parsed statement into a nested structure.
func statementToInterface(stmt *parsedStatement) (interface{}, error) {
	return ungronSegments(stmt, 0)
}

func ungronSegments(stmt *parsedStatement, i int) (interface{}, error) {
	if i >= len(stmt.segments) {
		return parseValueToken(stmt.value.text)
	}
	tok := stmt.segments[i]
	switch tok.kind {
	case tokNumber:
		idx, err := strconv.Atoi(tok.text)
		if err != nil {
			return nil, fmt.Errorf("invalid integer key `%s`", tok.text)
		}
		child, err := ungronSegments(stmt, i+1)
		if err != nil {
			return nil, err
		}
		arr := make([]interface{}, idx+1)
		arr[idx] = child
		return arr, nil
	case tokQuoted:
		child, err := ungronSegments(stmt, i+1)
		if err != nil {
			return nil, err
		}
		var key string
		if err := json.Unmarshal([]byte(tok.text), &key); err != nil {
			return nil, fmt.Errorf("invalid quoted key `%s`", tok.text)
		}
		return map[string]interface{}{key: child}, nil
	default: // bare
		child, err := ungronSegments(stmt, i+1)
		if err != nil {
			return nil, err
		}
		return map[string]interface{}{tok.text: child}, nil
	}
}

func mergeValues(a, b interface{}) (interface{}, error) {
	switch aT := a.(type) {
	case map[string]interface{}:
		bT, ok := b.(map[string]interface{})
		if !ok {
			return nil, errors.New("cannot merge object with non-object")
		}
		for k, bv := range bT {
			if av, exists := aT[k]; exists {
				merged, err := mergeValues(av, bv)
				if err != nil {
					return nil, err
				}
				aT[k] = merged
			} else {
				aT[k] = bv
			}
		}
		return aT, nil
	case []interface{}:
		bT, ok := b.([]interface{})
		if !ok {
			return nil, errors.New("cannot merge array with non-array")
		}
		for len(aT) < len(bT) {
			aT = append(aT, nil)
		}
		for i, bv := range bT {
			if bv == nil {
				continue
			}
			merged, err := mergeValues(aT[i], bv)
			if err != nil {
				return nil, err
			}
			aT[i] = merged
		}
		return aT, nil
	default:
		return b, nil
	}
}

// convertStatements runs classification, conversion and merging for a list of
// parsed statements. It returns the final value.
func convertStatements(stmts []*parsedStatement) (interface{}, error) {
	var merged interface{}
	any := false
	for _, stmt := range stmts {
		if stmt.isEmpty() || stmt.isSingleSkip() {
			continue
		}
		any = true
		if stmt.invalid {
			return nil, &stmtError{stmt, errInvalidStatement}
		}
		if !stmt.terminated {
			return nil, &stmtError{stmt, errNoValue}
		}
		v, err := statementToInterface(stmt)
		if err != nil {
			return nil, &stmtError{stmt, err}
		}
		merged, err = mergeValues(merged, v)
		if err != nil {
			return nil, fmt.Errorf("failed to merge statements: %s", err)
		}
	}
	if !any {
		return nil, errors.New("no statements were parsed")
	}
	if m, ok := merged.(map[string]interface{}); ok && len(m) == 1 {
		if v, ok := m["json"]; ok {
			return v, nil
		}
	}
	return merged, nil
}

func newStatementScanner(input io.Reader) *bufio.Scanner {
	scanner := bufio.NewScanner(input)
	scanner.Buffer(make([]byte, 0, 64*1024), 1024*1024)
	return scanner
}

func readTextStatements(input io.Reader) ([]*parsedStatement, error) {
	scanner := newStatementScanner(input)
	var stmts []*parsedStatement
	for scanner.Scan() {
		stmt := parseStatement(scanner.Text())
		s := stmt
		stmts = append(stmts, &s)
	}
	if err := scanner.Err(); err != nil {
		return nil, err
	}
	return stmts, nil
}

func jsonStatementFromLine(line string) (*parsedStatement, error) {
	var pair []interface{}
	if err := json.Unmarshal([]byte(line), &pair); err != nil {
		return nil, err
	}
	if len(pair) != 2 {
		return nil, errors.New("invalid JSON layout")
	}
	path, ok := pair[0].([]interface{})
	if !ok {
		return nil, errors.New("invalid JSON layout")
	}
	switch v := pair[1].(type) {
	case map[string]interface{}:
		if len(v) > 0 {
			return nil, errors.New("invalid JSON layout")
		}
	case []interface{}:
		if len(v) > 0 {
			return nil, errors.New("invalid JSON layout")
		}
	}
	stmt := &parsedStatement{hasEquals: true, valuePresent: true, terminated: true}
	stmt.pathDisplay = "json"
	stmt.tokenCount = 1
	stmt.segments = append(stmt.segments, ptoken{kind: tokBare, text: "json"})
	for _, el := range path {
		stmt.pathDisplay += "["
		stmt.tokenCount++
		switch t := el.(type) {
		case string:
			text := quoteString(t)
			stmt.pathDisplay += text
			stmt.tokenCount++
			stmt.segments = append(stmt.segments, ptoken{kind: tokQuoted, text: text})
		case float64:
			b, _ := json.Marshal(t)
			text := string(b)
			stmt.pathDisplay += text
			stmt.tokenCount++
			stmt.segments = append(stmt.segments, ptoken{kind: tokNumber, text: text})
		default:
			return nil, errors.New("invalid JSON layout")
		}
		stmt.pathDisplay += "]"
		stmt.tokenCount++
	}
	b, _ := json.Marshal(pair[1])
	stmt.value = ptoken{kind: tokGeneric, text: string(b)}
	return stmt, nil
}

func readJSONStatements(input io.Reader) ([]*parsedStatement, error) {
	scanner := newStatementScanner(input)
	var stmts []*parsedStatement
	for scanner.Scan() {
		stmt, err := jsonStatementFromLine(scanner.Text())
		if err != nil {
			// Syntax / layout errors are reported immediately by the caller
			// using a distinct exit path; encode that in the error type.
			return nil, &jsonLineError{err}
		}
		stmts = append(stmts, stmt)
	}
	if err := scanner.Err(); err != nil {
		return nil, err
	}
	return stmts, nil
}

type jsonLineError struct{ err error }

func (e *jsonLineError) Error() string { return e.err.Error() }

func encodeColorJSON(v interface{}, b *strings.Builder) {
	switch t := v.(type) {
	case map[string]interface{}:
		b.WriteString(cMagenta("{"))
		keys := make([]string, 0, len(t))
		for k := range t {
			keys = append(keys, k)
		}
		sort.Strings(keys)
		for i, k := range keys {
			if i > 0 {
				b.WriteString(cBold(","))
			}
			b.WriteString(cBlueBold("\""))
			b.WriteString(cBlueBold(jsonStringContent(k)))
			b.WriteString(cBlueBold("\""))
			b.WriteString(cBold(":"))
			encodeColorJSON(t[k], b)
		}
		b.WriteString(cMagenta("}"))
	case []interface{}:
		b.WriteString(cMagenta("["))
		for i, el := range t {
			if i > 0 {
				b.WriteString(cBold(","))
			}
			encodeColorJSON(el, b)
		}
		b.WriteString(cMagenta("]"))
	case string:
		b.WriteString(cGreen("\""))
		b.WriteString(cYellow(jsonStringContent(t)))
		b.WriteString(cGreen("\""))
	case json.Number:
		b.WriteString(cRed(t.String()))
	case bool:
		if t {
			b.WriteString(cCyan("true"))
		} else {
			b.WriteString(cCyan("false"))
		}
	case nil:
		b.WriteString(cCyan("null"))
	default:
		raw, _ := json.Marshal(t)
		b.WriteString(cRed(string(raw)))
	}
}

func outputUngron(v interface{}) {
	if colorOn {
		var b strings.Builder
		encodeColorJSON(v, &b)
		fmt.Println(b.String())
		return
	}
	var buf bytes.Buffer
	enc := json.NewEncoder(&buf)
	enc.SetEscapeHTML(false)
	enc.SetIndent("", "  ")
	if err := enc.Encode(v); err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(6)
	}
	fmt.Print(buf.String())
}

func doUngron(input io.Reader) {
	var stmts []*parsedStatement
	var err error
	if optJSON {
		stmts, err = readJSONStatements(input)
		if err != nil {
			if je, ok := err.(*jsonLineError); ok {
				fmt.Fprintln(os.Stderr, je.err)
				os.Exit(5)
			}
			fmt.Fprintln(os.Stderr, "failed to read input statements")
			os.Exit(2)
		}
	} else {
		stmts, err = readTextStatements(input)
		if err != nil {
			fmt.Fprintln(os.Stderr, "failed to read input statements")
			os.Exit(2)
		}
	}
	v, err := convertStatements(stmts)
	if err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(5)
	}
	outputUngron(v)
}

// ---------------------------------------------------------------------------
// Values mode
// ---------------------------------------------------------------------------

func doValues() {
	scanner := bufio.NewScanner(os.Stdin)
	for scanner.Scan() {
		line := scanner.Text()
		stmt := parseStatement(line)
		if stmt.isEmpty() {
			fmt.Fprintf(os.Stderr, "failed to parse '%s' as gron statement\n", line)
			os.Exit(5)
		}
		if stmt.invalid {
			continue
		}
		if stmt.isSingleSkip() {
			// Reproduce the original's crash for a lone "json" statement.
			if len(stmt.segments) == 1 && stmt.segments[0].kind == tokBare && stmt.segments[0].text == "json" {
				var empty []string
				_ = empty[0]
			}
			continue
		}
		if !stmt.hasEquals {
			continue
		}
		if !stmt.valuePresent {
			fmt.Println("")
			continue
		}
		switch stmt.value.kind {
		case tokObject, tokArray:
			continue
		case tokQuoted:
			var s string
			dec := json.NewDecoder(strings.NewReader(stmt.value.text))
			if err := dec.Decode(&s); err != nil {
				continue
			}
			fmt.Println(s)
		default:
			fmt.Println(stmt.value.text)
		}
	}
}
