new='''// quoteStdJSON encodes s like Go's JSON encoder, but uses the short
// escapes \\b and \\f (matching the reference, built with a newer
// encoding/json). If html is true, <, > and & are escaped as \\u00xx.
func quoteStdJSON(s string, html bool) string {
	var b strings.Builder
	b.WriteByte('"')
	i := 0
	for i < len(s) {
		c := s[i]
		if c < utf8.RuneSelf {
			i++
			switch c {
			case '"', '\\\\':
				b.WriteByte('\\\\')
				b.WriteByte(c)
			case '\\b':
				b.WriteString(`\\b`)
			case '\\f':
				b.WriteString(`\\f`)
			case '\\n':
				b.WriteString(`\\n`)
			case '\\r':
				b.WriteString(`\\r`)
			case '\\t':
				b.WriteString(`\\t`)
			case '<', '>', '&':
				if html {
					fmt.Fprintf(&b, `\\u%04x`, c)
				} else {
					b.WriteByte(c)
				}
			default:
				if c < 0x20 {
					fmt.Fprintf(&b, `\\u%04x`, c)
				} else {
					b.WriteByte(c)
				}
			}
			continue
		}
		r, size := utf8.DecodeRuneInString(s[i:])
		if r == utf8.RuneError && size == 1 {
			b.WriteString(`\\ufffd`)
			i++
			continue
		}
		if r == '\\u2028' || r == '\\u2029' {
			fmt.Fprintf(&b, `\\u%04x`, r)
		} else {
			b.WriteString(s[i : i+size])
		}
		i += size
	}
	b.WriteByte('"')
	return b.String()
}

func jsonStringContent(s string) string {
	out := quoteStdJSON(s, false)
	return out[1 : len(out)-1]
}'''
